package com.eldenworld.core.specialization;
import com.eldenworld.core.EldenWorldCore; import com.eldenworld.core.abilities.AbilityUtil; import net.minecraft.server.level.ServerPlayer; import net.minecraft.world.entity.Entity; import net.minecraft.world.entity.OwnableEntity; import net.minecraftforge.event.entity.living.LivingHurtEvent; import net.minecraftforge.eventbus.api.SubscribeEvent; import net.minecraftforge.fml.common.Mod;
@Mod.EventBusSubscriber(modid=EldenWorldCore.MOD_ID) public final class PetMasteryEvents {private PetMasteryEvents(){} @SubscribeEvent public static void onHurt(LivingHurtEvent e){Entity a=e.getSource().getEntity(); if(a instanceof OwnableEntity p&&p.getOwner() instanceof ServerPlayer o&&AbilityUtil.has(o,SpecializationIds.BEASTMASTER))e.setAmount(e.getAmount()*1.20f); if(e.getEntity() instanceof OwnableEntity p&&p.getOwner() instanceof ServerPlayer o&&AbilityUtil.has(o,SpecializationIds.BEASTMASTER))e.setAmount(e.getAmount()*.85f); if(e.getEntity() instanceof ServerPlayer r&&r.getVehicle()!=null&&AbilityUtil.has(r,SpecializationIds.DRAGON_RIDER))e.setAmount(e.getAmount()*.90f);}}
